// Script to read .env.test and POST its contents as JSON to a remote endpoint
const fs = require('fs');
const axios = require('axios');

// Read the .env.test file
const envData = fs.readFileSync('.env.test', 'utf-8');

// Parse the lines into an object
const envVars = {};
const lines = envData.split('\n');
lines.forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    if (key && value) {
      envVars[key] = value;
    }
  }
});

// Prepare the JSON payload
const payload = {
  env: envVars,
  source: '.env.test',
  timestamp: new Date().toISOString(),
};

// Post the payload to the remote endpoint
axios.post('http://localhost:47301/api/doc-export', payload)
  .then(response => {
    console.log('Successfully posted environment variables:', response.status);
  })
  .catch(error => {
    console.error('Failed to post environment variables:', error.message);
  });

