#!/usr/bin/env node
// Script to read .env.test and POST its contents as JSON to a remote endpoint
const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envData = fs.readFileSync('.env.test', 'utf-8');

// Parse the lines into an object
const envVars = {};
const lines = envData.split('\n');
lines.forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    if (key && value) {
      envVars[key] = value;
    }
  }
});

// Prepare the JSON payload
const payload = {
  env: envVars,
  source: '.env.test',
  timestamp: new Date().toISOString(),
};

console.log('Payload to be sent:', JSON.stringify(payload, null, 2));

// Post the payload using Node's built-in https module
const postData = JSON.stringify(payload);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
  },
};

const req = https.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  res.on('data', (chunk) => {
    console.log('Response:', chunk.toString());
  });
});

req.on('error', (error) => {
  console.error('Failed to post environment variables:', error.message);
});

req.write(postData);
req.end();

